window.ScripturaLexicons.BDAG_PART_0320 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0320-01\" data-source=\"BDAG\" data-search=\"σαρκίον, ου, τό substantivo neutro pedaço de carne BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σαρκίον, ου, τό</td><td>substantivo neutro</td><td>pedaço de carne</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0320-02\" data-source=\"BDAG\" data-search=\"σαρκοφάγος, ον adjetivo carnívoro BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σαρκοφάγος, ον</td><td>adjetivo</td><td>carnívoro</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0320-03\" data-source=\"BDAG\" data-search=\"σαρκοφόρος, ον adjetivo ou substantivo portador de carne BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σαρκοφόρος, ον</td><td>adjetivo ou substantivo</td><td>portador de carne</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0320-04\" data-source=\"BDAG\" data-search=\"σάρξ, σαρκός, ἡ substantivo feminino carne; corpo; ser humano; natureza mortal; condição exterior BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σάρξ, σαρκός, ἡ</td><td>substantivo feminino</td><td>carne; corpo; ser humano; natureza mortal; condição exterior</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0320-05\" data-source=\"BDAG\" data-search=\"σάρος, ου, ὁ substantivo masculino vassoura BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σάρος, ου, ὁ</td><td>substantivo masculino</td><td>vassoura</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0320-06\" data-source=\"BDAG\" data-search=\"Σαρούχ nome próprio; variante ver Σερούχ BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Σαρούχ</td><td>nome próprio; variante</td><td>ver Σερούχ</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0320-07\" data-source=\"BDAG\" data-search=\"σαρόω verbo varrer BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σαρόω</td><td>verbo</td><td>varrer</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0320-08\" data-source=\"BDAG\" data-search=\"Σάρρα, ας, ἡ nome próprio feminino Sara BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Σάρρα, ας, ἡ</td><td>nome próprio feminino</td><td>Sara</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0320-09\" data-source=\"BDAG\" data-search=\"Σαρ(ρ)ων, ωνος, ὁ nome próprio masculino Sarom BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Σαρ(ρ)ων, ωνος, ὁ</td><td>nome próprio masculino</td><td>Sarom</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0320-10\" data-source=\"BDAG\" data-search=\"σατάν, ὁ nome masculino indeclinável; nome próprio Satanás, adversário BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σατάν, ὁ</td><td>nome masculino indeclinável; nome próprio</td><td>Satanás, adversário</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0320-11\" data-source=\"BDAG\" data-search=\"σάτον, ου, τό substantivo neutro seá, medida de treze litros BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σάτον, ου, τό</td><td>substantivo neutro</td><td>seá, medida de treze litros</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0320-12\" data-source=\"BDAG\" data-search=\"Σαῦλος, ου, ὁ nome próprio masculino Saulo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Σαῦλος, ου, ὁ</td><td>nome próprio masculino</td><td>Saulo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0320-13\" data-source=\"BDAG\" data-search=\"σαφῶς advérbio claramente, exatamente, muito bem BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σαφῶς</td><td>advérbio</td><td>claramente, exatamente, muito bem</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0320-14\" data-source=\"BDAG\" data-search=\"σβέννυμι verbo apagar; sufocar, suprimir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σβέννυμι</td><td>verbo</td><td>apagar; sufocar, suprimir</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0320-15\" data-source=\"BDAG\" data-search=\"σέ pronome; remissão ver σύ BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σέ</td><td>pronome; remissão</td><td>ver σύ</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0320-16\" data-source=\"BDAG\" data-search=\"σεαυτοῦ pronome reflexivo de ti mesmo, a ti mesmo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σεαυτοῦ</td><td>pronome reflexivo</td><td>de ti mesmo, a ti mesmo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0320-17\" data-source=\"BDAG\" data-search=\"σεβάζομαι verbo depoente reverenciar, adorar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σεβάζομαι</td><td>verbo depoente</td><td>reverenciar, adorar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0320-18\" data-source=\"BDAG\" data-search=\"σέβασμα, ατος, τό substantivo neutro objeto de devoção BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σέβασμα, ατος, τό</td><td>substantivo neutro</td><td>objeto de devoção</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0320-19\" data-source=\"BDAG\" data-search=\"σεβάσμιος, ον adjetivo venerável, honroso BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σεβάσμιος, ον</td><td>adjetivo</td><td>venerável, honroso</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0320-20\" data-source=\"BDAG\" data-search=\"σεβαστός, ή, όν adjetivo; título venerável, augusto BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σεβαστός, ή, όν</td><td>adjetivo; título</td><td>venerável, augusto</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0320-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σαρκίον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σαρκίον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> dimin. de <span class=\"greek\">σάρξ</span> uma parte ou pedaço de um corpo, pedaço de carne, porção de carne (Hippocr. et al.; M. Ant. 2, 2, 1; 2) de um corpo inteiro (‘porção de carne’ Plut., Brut. 987 [8, 3]) <span class=\"greek\">κοινωνῆσαι</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ἁγίῳ</span>(<span class=\"greek\">κοινωνέω</span> 1b<span class=\"greek\">α</span>) partilhar alguns momentos com sua santa porção de carne MPol 17:1.—DELG s.v. <span class=\"greek\">σάρξ</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0320-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σαρκοφάγος, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σαρκοφάγος</span>, <span class=\"greek\">ον</span> (<span class=\"greek\">σάρξ</span>, <span class=\"greek\">φαγεῖν</span>; Aristot. et al.; cf. EpArist 146; SibOr 2, 236) carnívoro <span class=\"greek\">θηρία</span> <span class=\"greek\">λεπτὰ</span> <span class=\"greek\">ς</span>. de vermes ApcPt Fgm. 2.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0320-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σαρκοφόρος, ον</h1><div class=\"entry-meta\"><span>adjetivo ou substantivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σαρκοφόρος</span>, <span class=\"greek\">ον</span> (<span class=\"greek\">σάρξ</span> + <span class=\"greek\">φέρω</span> por intermédio de <span class=\"greek\">φόρος</span>; Nicetas Eugen. 3, 319 Hercher; de seres humanos SibOr 8, 222; de Cristo 1, 325; Clem. de Alex., Strom. 5, 34, 1) portador de carne, da manifestação de Cristo em verdadeira forma humana <span class=\"greek\">ὁμολογεῖν</span> <span class=\"greek\">αὐτὸν</span> (=<span class=\"greek\">κύριον</span>) <span class=\"greek\">σαρκοφόρον</span> confessar que ele estava revestido de carne (adj. ou subst.) ISm 5:2.—Cf. formas s.v. <span class=\"greek\">φέρω</span> em DELG p. 1190.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0320-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σάρξ, σαρκός, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σάρξ</span>, <span class=\"greek\">σαρκός</span>, <span class=\"greek\">ἡ</span> (Hom.+; ‘carne’).</p><p class=\"entry-text\">① a matéria que recobre os ossos de um corpo humano ou animal, carne lit. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.39\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:39</a>abcd; Hv 3, 10, 4; 3, 12, 1. O pl. (que denota carne em sua totalidade material [Lucian, Dial. Mort. 10, 5], ao passo que o sing. denota antes a substância.—Herodas 4, 61; Gen 40:19; 1 Km 17:44; 4 Km 9:36; PsSol 4:19; TestJob 13:5; Philo; Jos., Ant. 12, 211; Just., A I, 26, 7; Mel., P. 52, 383; Ath. 34, 2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.39\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:39</a> v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.19.18\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 19:18</a>, 21 (4 [6] Esdr [POxy 1010, 16] canibalismo por fome, semelhantemente Mel., P. 52, 383; Quint. Smyrn. 11, 245: as <span class=\"greek\">σάρκες</span> dos mortos são alimento para as aves) B 10:4; metaf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.17.16\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 17:16</a>. Decompõe-se 1 Cl 25:3; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.31\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:31</a> (cf. 2a abaixo). Normalmente exala mau odor quando queimada MPol 15:2. Com ossos (v. <span class=\"greek\">ὀστέον</span>) 1 Cl 6:3 (Gen 2:23); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.39\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:39</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.30\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 5:30</a> v.l. (metaf.). Paulo fala de sua enfermidade como um <span class=\"greek\">σκόλοψ</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">σαρκί</span> (v. <span class=\"greek\">σκόλοψ</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.7\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 12:7</a>. <span class=\"greek\">ἡ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">σαρκὶ</span> <span class=\"greek\">περιτομή</span> a circuncisão física (cf. Just., D. 10, 1 al.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.28\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 2:28</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 2:11</a>b; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:13</a> (<span class=\"greek\">ἀκροβυστία</span> 2); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.6.13\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 6:13</a> (<span class=\"greek\">ἡ</span> <span class=\"greek\">σάρξ</span>=a carne que é circuncidada); B 9:4. Metaf.: a corrosão dos metais preciosos dos ricos <span class=\"greek\">φάγεται</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">σάρκας</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">πῦρ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.3\" target=\"_blank\" rel=\"noopener noreferrer\">Js 5:3</a>.—Ign. descreve os elementos da Eucaristia como <span class=\"greek\">σὰρξ</span> (ou <span class=\"greek\">αἷμα</span>) <span class=\"greek\">Ἰησοῦ</span> <span class=\"greek\">Χριστοῦ</span> IRo 7:3; IPhld 4; ISm 7:1. Também <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.51\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:51</a>–56 insiste em que se deve comer a carne (e beber o sangue) do Ser Humano ou Filho do Homem (Just., A I, 66, 2; v. TPhilips, Die Verheissung der hl. Eucharistie nach Joh. 1922; Bultmann ad loc.; AWikenhauser ’48, 105f).—Sua posição antidocética também leva Ign. a empregar o conceito ‘carne (e sangue) de Cristo’ em outros contextos ITr 8:1; IPhld 5:1.—Para <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.16.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 16:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 1:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.12\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 6:12</a>; e <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.50\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:50</a> v. 3a.</p><p class=\"entry-text\">② o corpo físico como entidade em funcionamento, corpo, corpo físico</p><p class=\"entry-text\">ⓐ como substância e entidade viva (Aeschyl., Sept. 622: op. <span class=\"greek\">νοῦς</span>; Ex 30:32; 4 Km 6:30; TestAbr A 20 p. 103, 6 [Stone p. 54] <span class=\"greek\">πάντα</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">μέλη</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">σαρκός</span> <span class=\"greek\">μου</span>; com <span class=\"greek\">καρδία</span> ou <span class=\"greek\">ψυχή</span> Alex. Aphr., An. p. 98, 7–10 Br.; Ps 37:8; 62:2; Eccl 2:3; Ezk 11:19; 44:7 a1.; Jos., Bell. 6, 47, Ant. 19, 325; Ar.15, 7) <span class=\"greek\">οὔτε</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">σὰρξ</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">εἶδεν</span> <span class=\"greek\">διαφθοράν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.31\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:31</a> (mas v. 1). Com <span class=\"greek\">ψυχή</span> 1 Cl 49:6 (Tat. 13:2 al.). Com <span class=\"greek\">καρδία</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:26</a> (Ps 15:9).—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.29\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 5:29</a>. <span class=\"greek\">ἑόρακαν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πρόσωπόν</span> <span class=\"greek\">μου</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">σαρκί</span> viram-me face a face <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:1</a>. <span class=\"greek\">ἕως</span> <span class=\"greek\">ἂν</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">χριστὸν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">σαρκὶ</span> <span class=\"greek\">ἴδῃ</span> antes que tivesse visto o Messias em pessoa GJs 24:4 (cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.26\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:26</a>). Op. <span class=\"greek\">πνεῦμα</span> (Ath. 31:3; PGM 5, 460 <span class=\"greek\">ἐπικαλοῦμαί</span> <span class=\"greek\">σε</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">κτίσαντα</span> <span class=\"greek\">πᾶσαν</span> <span class=\"greek\">σάρκα</span> <span class=\"greek\">κ</span>. <span class=\"greek\">πᾶν</span> <span class=\"greek\">πνεῦμα</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.5.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 5:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.7.1\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 7:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 4:6</a>; Hm 3:1; 10, 2, 6; cf. AcPl Ant 13:17 (=Aa, I 237, 2; v. <span class=\"greek\">οἶδα</span>); também em relação a Cristo (embora isso seja discutido) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.63\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:63</a>; Hs 5, 6, 5–7; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 3:16</a>.—<span class=\"greek\">ἀσθένεια</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">σαρκός</span> enfermidade corporal <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.13\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:13</a>; v. vs. 14. <span class=\"greek\">ἀσθενὴς</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">σαρκί</span> fraco no corpo Hs 9, 1, 2. <span class=\"greek\">ὁ</span> <span class=\"greek\">ἀλγῶν</span> <span class=\"greek\">σάρκα</span> aquele que está enfermo no corpo B 8:6. <span class=\"greek\">πάσχειν</span> <span class=\"greek\">σαρκί</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 4:1</a>b. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.7.5\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 7:5</a>. <span class=\"greek\">ἡ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">σαρκὸς</span> <span class=\"greek\">καθαρότης</span> a pureza do corpo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.13\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:13</a> (op. <span class=\"greek\">καθαρίζειν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">συνείδησιν</span> vs. 14). <span class=\"greek\">σαρκὸς</span> <span class=\"greek\">ἀπόθεσις</span> <span class=\"greek\">ῥύπου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.21\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 3:21</a> (v. <span class=\"greek\">ῥύπος</span> 1). A <span class=\"greek\">σάρξ</span> é ressuscitada dentre os mortos (v. ParJer 6:9; Theoph. Ant. 1, 7 [74, 2]) 1 Cl 26:3; 2 Cl 9:1. <span class=\"greek\">ἀνάστασις</span> <span class=\"greek\">σαρκός</span> AcPlCor 1:12; 2:24 (<span class=\"greek\">σαρκὸς</span> <span class=\"greek\">ἀνάστασιν</span> Just., D. 80, 5); cf. <span class=\"greek\">ἀναστήσεσθε</span> <span class=\"greek\">ἔχοντες</span> <span class=\"greek\">ὑγιῆ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">σάρκα</span> AcPlCor 2:32. Do corpo de Cristo durante seu ministério terreno <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 2:14</a> (JHart, The Enmity in His Flesh: Exp. 6th ser., 3, 1901, 135–41); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.20\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.18\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 3:18</a>; 4:1a; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.4.2\" target=\"_blank\" rel=\"noopener noreferrer\">1J 4:2</a>; 2J 7; B 5:1, 10f; 6:7, 9; 7:5; 12:10; IEph 7:2; Pol 7:1; AcPlCor 2:6b. Os cônjuges constituem <span class=\"greek\">μία</span> <span class=\"greek\">σάρξ</span> (Gen 2:24; v. Ath. 33, 2 <span class=\"greek\">τὴν</span> <span class=\"greek\">σάρκα</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">σάρκα</span> … <span class=\"greek\">κοινωνίαν</span>.—GAicher, Mann u. Weib ein Fleisch: BZ 5, 1907, 159–65) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.19.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 19:5</a>f; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:8</a>ab; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.6.16\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 6:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.31\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 5:31</a> (sobre essas passagens, TBurkill, ZNW 62, ’71, 115–20). <span class=\"greek\">δικαιώματα</span> <span class=\"greek\">σαρκός</span> por trás de ‘toda sorte de lavagens cerimoniais’ há prescrições que dizem respeito ao corpo físico <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.10\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:10</a>.—Sobre <span class=\"greek\">ὑποτάγητε</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ἐπισκόπῳ</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">Χριστὸς</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">πατρὶ</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">σάρκα</span> IMg 13:2 v. Hdb. ad loc. e MRackl, Die Christologie des hl. Ignatius v. Ant. 1914, 228.—<span class=\"greek\">πνεῦμα</span> <span class=\"greek\">δυνάμεως</span> … <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> … <span class=\"greek\">κατέπεμψεν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">σάρκα</span> <span class=\"greek\">τουτέστιν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">Μαρίαν</span> Deus enviou um espírito poderoso (provavelmente ref. à espécie de sopro divino que trouxe à vida o primeiro ser humano [Gen 2:7]) à carne, isto é, a Maria AcPl Ha 8, 26=BMM recto 34; v. AcPlCor 1:14.</p><p class=\"entry-text\">ⓑ como algo com limitações físicas, vida aqui na terra (ApcEsdr 4:4 p. 28, 3 Tdf. <span class=\"greek\">σάρκα</span> <span class=\"greek\">ἀνθρωπίνην</span> <span class=\"greek\">φορῶ</span>) <span class=\"greek\">θλῖψιν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">σαρκὶ</span> <span class=\"greek\">ἕξουσιν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.28\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:28</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.4.11\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 4:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.24\" target=\"_blank\" rel=\"noopener noreferrer\">Col 1:24</a>. De Cristo <span class=\"greek\">τὸ</span> <span class=\"greek\">σῶμα</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">σαρκὸς</span> <span class=\"greek\">αὐτοῦ</span> seu corpo com suas limitações físicas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.22\" target=\"_blank\" rel=\"noopener noreferrer\">Col 1:22</a>; cf. 2:11 e v. c<span class=\"greek\">α</span> abaixo (cf. En 102:5 <span class=\"greek\">τὸ</span> <span class=\"greek\">σῶμα</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">σαρκὸς</span> <span class=\"greek\">ὑμῶν</span>; 1QpHab 9:2; Orig., C. Cels. 6, 29, 25).—Da vida humana: <span class=\"greek\">ἀποδημεῖν</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">σαρκός</span> MPol 2:2 (v. <span class=\"greek\">ἀποδημέω</span>). <span class=\"greek\">ἐπιμένειν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">σαρκί</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.24\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:24</a>. <span class=\"greek\">ζῆν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">σαρκί</span> vs. 22; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.20\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 2:20</a>. <span class=\"greek\">ἐν</span> <span class=\"greek\">ς</span>. <span class=\"greek\">περιπατεῖν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.10.3\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 10:3</a>a. <span class=\"greek\">ἐν</span> <span class=\"greek\">ς</span>. <span class=\"greek\">τυγχάνειν</span> Dg 5:8a. <span class=\"greek\">ὄντος</span> <span class=\"greek\">ἔτι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ς</span>. <span class=\"greek\">σου</span> AcPlCor 1:6. <span class=\"greek\">τὸν</span> <span class=\"greek\">ἐπίλοιπον</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ς</span>. <span class=\"greek\">χρόνον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.4.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 4:2</a>. <span class=\"greek\">ἡ</span> <span class=\"greek\">ἐπιδημία</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">σαρκὸς</span> <span class=\"greek\">ταύτης</span> nossa permanência nesta vida 2 Cl 5:5. <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">σαρκί</span> em nossa vida terrena 8:2.</p><p class=\"entry-text\">ⓒ como instrumento de diversas ações ou expressões.</p><p class=\"entry-text\"><span class=\"greek\">α</span>. Especialmente no pensamento de Paulo, todas as partes do corpo constituem uma totalidade conhecida como <span class=\"greek\">ς</span>. ou carne, dominada pelo pecado a tal ponto que, onde quer que esteja a carne, todas as formas de pecado estão igualmente presentes, e nenhuma coisa boa pode habitar na <span class=\"greek\">σάρξ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.7.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 7:18</a> (cf. Philo, Gig. 29 <span class=\"greek\">αἴτιον</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀνεπιστημοσύνης</span> <span class=\"greek\">μέγιστον</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">σὰρξ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">σάρκα</span> <span class=\"greek\">οἰκείωσις</span>; Sextus 317 <span class=\"greek\">ἀγαθὸν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">σαρκὶ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">ἐπιζήτει</span>. O AT não enfatiza uma relação necessária entre a carne como substância e o pecado. Mas para Epicuro a <span class=\"greek\">σάρξ</span> é portadora de sentimentos e desejos pecaminosos, bem como o meio de fruição sensual: Ep. em Plut., Mor. 135c; 1087bf; 1089e; 1096c <span class=\"greek\">αἱ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">σαρκὸς</span> <span class=\"greek\">ἐπιθυμίαι</span>. Também Diog. L. 10, 145. Igualmente o próprio Plut.: Mor. 101b <span class=\"greek\">ταῖς</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">σαρκὸς</span> <span class=\"greek\">ἡδοναῖς</span>; 672e; 688d; 734a; Ps.-Plut., Mor. 107f <span class=\"greek\">σαρκὶ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">πάθεσι</span> <span class=\"greek\">ταύτης</span>; Maximus Tyr. 33, 7a. Cf. 4 Macc 7:18 <span class=\"greek\">τὰ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">σαρκὸς</span> <span class=\"greek\">πάθη</span>; Philo, Deus Imm. 143 <span class=\"greek\">σαρκὸς</span> <span class=\"greek\">ἡδονή</span>, Gig. 29; TestJud 19:4; TestZeb 9:7; ApcMos 25 [p. 14, 2 Tdf.] <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἁμαρτίαν</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">σαρκός</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.6.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 6:19</a>; 7:25 (op. <span class=\"greek\">νοῦς</span>); 8:3a, 4–9 (cf. Persius 2, 63 scelerata pulpa, que contamina a devoção à divindade), 12f; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.13\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 5:13</a>, 24; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.23\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:23</a>; Jd 23; AcPlCor 2:11, 15; Dg 6:5 (op. <span class=\"greek\">ψυχή</span>, como Plut., Mor. 101b). Op. <span class=\"greek\">τὸ</span> <span class=\"greek\">πνεῦμα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:4</a>, 5, 6, 9, 13; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 3:3</a>; 5:16, 17ab; 6:8ab; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.6\" target=\"_blank\" rel=\"noopener noreferrer\">J 3:6</a>; B 10:9. <span class=\"greek\">τὸ</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">πρόθυμον</span>, <span class=\"greek\">ἡ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">σὰρξ</span> <span class=\"greek\">ἀσθενής</span> (cf. Orig., C. Cels. 2, 25, 8) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.41\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:41</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.38\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:38</a>; Pol 7:2. <span class=\"greek\">σὰρξ</span> <span class=\"greek\">ἁμαρτίας</span> carne pecaminosa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:3</a>b. <span class=\"greek\">ἐπιθυμία</span> (<span class=\"greek\">τῆς</span>) <span class=\"greek\">σαρκός</span> (cf. Maximus Tyr. 20, 9f <span class=\"greek\">σαρκῶν</span> … <span class=\"greek\">ἐπιθυμίας</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.16\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 5:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.2.16\" target=\"_blank\" rel=\"noopener noreferrer\">1J 2:16</a>; B 10:9. Pl. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 2:3</a>a, cf. b; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.18\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 2:18</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.13.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 13:14</a>. <span class=\"greek\">τὰ</span> <span class=\"greek\">ἔργα</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">σαρκός</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.19\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 5:19</a> (v. Vögtle em <span class=\"greek\">πλεονεξία</span>). <span class=\"greek\">τὰ</span> <span class=\"greek\">θελήματα</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">σαρκός</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 2:3</a>b. <span class=\"greek\">ὁ</span> <span class=\"greek\">νοῦς</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">σαρκός</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.18\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:18</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">σῶμα</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">σαρκός</span> o corpo de carne (pecaminosa) 2:11; cf. 1:22 e v. b acima (cf. Sir 23:17 <span class=\"greek\">σῶμα</span> <span class=\"greek\">σαρκὸς</span> <span class=\"greek\">αὐτοῦ</span>; En 102:5 <span class=\"greek\">τῷ</span> <span class=\"greek\">σώματι</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">σαρκὸς</span> <span class=\"greek\">ὑμῶν</span>). <span class=\"greek\">τὰ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">σαρκός</span> aquilo que pertence à carne (pecaminosa) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:5</a>b. <span class=\"greek\">ἐν</span> (<span class=\"greek\">τῇ</span>) <span class=\"greek\">σαρκὶ</span> <span class=\"greek\">εἶναι</span> estar em condição não regenerada (e pecaminosa) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.7.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 7:5</a>; 8:8f. <span class=\"greek\">τὰ</span> <span class=\"greek\">ἔθνη</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">σαρκί</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 2:11</a>a. <span class=\"greek\">κατὰ</span> <span class=\"greek\">σάρκα</span> <span class=\"greek\">εἶναι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:5</a>a; <span class=\"greek\">ζῆν</span> vs. 12b; 13; Dg 5:8b; <span class=\"greek\">περιπατεῖν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.10.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 10:2</a>; <span class=\"greek\">βουλεύεσθαι</span> 1:17; <span class=\"greek\">στρατεύεσθαι</span> 10:3b; cf. IRo 8:3 (op. <span class=\"greek\">κατὰ</span> <span class=\"greek\">γνώμην</span> <span class=\"greek\">θεοῦ</span>).</p><p class=\"entry-text\"><span class=\"greek\">β</span>. fonte do impulso sexual. A <span class=\"greek\">σάρξ</span> é a fonte do impulso sexual, sem qualquer sugestão de pecaminosidade associada a ele <span class=\"greek\">ἐκ</span> <span class=\"greek\">θελήματος</span> <span class=\"greek\">σαρκὸς</span> <span class=\"greek\">ἐγεννήθησαν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:13</a>.</p><p class=\"entry-text\">ⓓ como algo atraente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 2:10</a> (um hebraísmo, cf. Judg 2:12; 3 Km 11:10; Sir 46:10). V. também 3b.</p><p class=\"entry-text\">③ aquele que é ou se torna um ser físico, ser vivo dotado de carne</p><p class=\"entry-text\">ⓐ de seres humanos, pessoa, ser humano: <span class=\"greek\">πᾶσα</span> <span class=\"greek\">σάρξ</span> toda pessoa, todos (LXX; TestAbr B 7 p. 112, 3 [Stone p. 72]; GrBar 4:10; ApcEsdr 7:7; ApcMos 13 [p. 7, 1 Tdf.]; Mel., P. 55, 400: por <span class=\"hebrew\">כָּל</span>-<span class=\"hebrew\">בָּשָׂר</span>; v. <span class=\"greek\">πᾶς</span> 1a<span class=\"greek\">α</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.6\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:6</a> (Is 40:5); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.17.2\" target=\"_blank\" rel=\"noopener noreferrer\">J 17:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:17</a> (Jo 3:1); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.24\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:24</a> (Is 40:6); 1 Cl 59:3; 64; 2 Cl 7:6; 17:5 (as duas últimas passagens Is 66:24); AcPlCor 2:6a. <span class=\"greek\">οὐ</span> <span class=\"greek\">πᾶσα</span> <span class=\"greek\">σάρξ</span> nenhuma pessoa, ninguém (En 14:21 fim.—W-S. §26, 10a; B-D-F §275, 4; 302, 1; Rob. 752) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:20</a> (cf. Ps 142:2 <span class=\"greek\">πᾶς</span> <span class=\"greek\">ζῶν</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.29\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:29</a> (<span class=\"greek\">μή</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.16\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 2:16</a>.—Embora <span class=\"greek\">ς</span>. nas passagens seguintes se refira ao corpo em seu aspecto físico, não pode ser dissociada de sua conjunção com <span class=\"greek\">αἷμα</span>, e a unidade <span class=\"greek\">σὰρξ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">αἷμα</span> (cf. Sir 17:31; TestAbr B 13 p. 117, 26 [Stone p. 82]; Philo, Quis Div. Rer. Her. 57; Just., D. 135, 6) refere-se a um ser humano em contraste com Deus e outros seres transcendentes <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.16.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 16:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 1:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.12\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 6:12</a> (aqui na ordem inversa, <span class=\"greek\">αἷ</span>. <span class=\"greek\">καὶ</span> <span class=\"greek\">ς</span>.). <span class=\"greek\">τὰ</span> <span class=\"greek\">παιδία</span> <span class=\"greek\">κεκοινώνηκεν</span> <span class=\"greek\">αἵματος</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">σαρκός</span> os filhos compartilham a natureza mortal <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2:14</a>, mas com sugestão de sua fragilidade, como indica o contexto com sua ref. à morte. Por serem opostos à natureza divina <span class=\"greek\">σὰρξ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">αἷμα</span> <span class=\"greek\">βασιλείαν</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">κληρονομῆσαι</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">δύναται</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.50\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:50</a> (JJeremias, NTS 2, ’56, 151–59). Para Jd 7 v. b a seguir. Cf. AcPl Ant 13, 17 (=Aa I 237, 2) <span class=\"greek\">σαρκί</span> pessoalmente (v. <span class=\"greek\">οἶδα</span> 2).</p><p class=\"entry-text\">ⓑ de entidades transcendentes <span class=\"greek\">ὁ</span> <span class=\"greek\">λόγος</span> <span class=\"greek\">σὰρξ</span> <span class=\"greek\">ἐγένετο</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.14\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:14</a> (RSeeberg, Festgabe AvHarnack dargebracht 1921, 263–81.—Artem. 2, 35 p. 132, 27 <span class=\"greek\">ἐὰν</span> <span class=\"greek\">σάρκινοι</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">θεοὶ</span> <span class=\"greek\">φαίνωνται</span>; Synes., Dio 6 p. 45b).—De carne diversa da humana: <span class=\"greek\">ὀπίσω</span> <span class=\"greek\">σαρκὸς</span> <span class=\"greek\">ἑτέρας</span> atrás de outra espécie de carne (cf. Judg 2:12 <span class=\"greek\">ὀπίσω</span> <span class=\"greek\">θεῶν</span> <span class=\"greek\">ἑτέρων</span>) isto é, de mensageiros divinos que assumem <span class=\"greek\">ς</span>. quando aparecem a seres humanos (assim Windisch et al.; diversamente Frame et al., de atividade entre pessoas do mesmo sexo) Jd 7.</p><p class=\"entry-text\">④ ligação humana/ancestral, natureza humana/mortal, descendência terrena (Did., Gen. 144, 25) <span class=\"greek\">Ἀβραὰμ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">προπάτορα</span> <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">σάρκα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 4:1</a> (Just., D. 43, 7 al.). <span class=\"greek\">οἱ</span> <span class=\"greek\">συγγενεῖς</span> <span class=\"greek\">μου</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">σάρκα</span> 9:3. <span class=\"greek\">τοὺς</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">σαρκὸς</span> <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">πατέρας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.9\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:9</a>. <span class=\"greek\">τὸν</span> <span class=\"greek\">Ἰσραὴλ</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">σάρκα</span> o Israel terreno <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.18\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 10:18</a> (op. <span class=\"greek\">τὸν</span> <span class=\"greek\">Ἰσραὴλ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.6.16\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 6:16</a>). Da descendência natural <span class=\"greek\">τὰ</span> <span class=\"greek\">τέκνα</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">σαρκός</span> filhos por descendência natural <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:8</a> (op. <span class=\"greek\">τὰ</span> <span class=\"greek\">τέκνα</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἐπαγγελίας</span>). <span class=\"greek\">ὁ</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">παιδίσκης</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">σάρκα</span> <span class=\"greek\">γεγέννηται</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.23\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:23</a>; cf. vs. 29. <span class=\"greek\">μου</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">σάρκα</span> meus compatriotas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 11:14</a> (v. Gen 37:27).—Da natureza física de Cristo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:3</a>c; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.5.7\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 5:7</a>. Cristo descende dos patriarcas e de Davi (<span class=\"greek\">τὸ</span>) <span class=\"greek\">κατὰ</span> <span class=\"greek\">σάρκα</span> segundo o aspecto humano de sua natureza, no que diz respeito à sua descendência física <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:3</a> (JDunn, Jesus: Flesh and Spirit [<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:3</a>f], JTS 24, ’73, 40–68); 9:5; 1 Cl 32:2; IEph 20:2. O contexto de <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.18\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 11:18</a> inclui a ascendência como motivo de glória, mas <span class=\"greek\">ς</span>. nessa pass. aplica-se também a outros aspectos da trajetória de Paulo e, portanto, pertence mais propriamente a 5.</p><p class=\"entry-text\">⑤ o aspecto exterior da vida tal como determinado por perspectivas ou padrões normais, sentido transf. de 1 e 2. Geralmente com <span class=\"greek\">κατά</span> indicando norma ou padrão <span class=\"greek\">σοφοὶ</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">σάρκα</span> (pessoas) sábias segundo padrões humanos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.26\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:26</a>. <span class=\"greek\">καυχᾶσθαι</span> <span class=\"greek\">κατὰ</span> (<span class=\"greek\">τὴν</span>) <span class=\"greek\">σάρκα</span> gloriar-se de suas circunstâncias exteriores, isto é, descendência, modo de vida etc. (cf. 11:22) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.18\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 11:18</a>. <span class=\"greek\">κατὰ</span> <span class=\"greek\">σάρκα</span> <span class=\"greek\">Χριστόν</span> Cristo (o Messias) de um ponto de vista humano ou no que concerne aos aspectos exteriores 5:16b, cf. a (<span class=\"greek\">κατά</span> B5b<span class=\"greek\">β</span> e 7a; também VWeber, BZ 2, 1904, 178–88; HWindisch, exc. ad loc.; Rtzst., Mysterienrel.3, 374–76; FPorter, Does Paul Claim to Have Known the Historical Jesus [<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.5.16\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 5:16</a>]?: JBL 47, 1928, 257–75; RMoxon, CQR 108, 1929, 320–28). <span class=\"greek\">οἱ</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">σάρκα</span> <span class=\"greek\">κύριοι</span> aqueles que, segundo padrões humanos, são senhores <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.5\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 6:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.22\" target=\"_blank\" rel=\"noopener noreferrer\">Col 3:22</a>. <span class=\"greek\">ὑμεῖς</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ς</span>. <span class=\"greek\">κρίνετε</span> julgais pelas coisas exteriores, pelas aparências <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.15\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:15</a>. Do caminho percorrido na vida terrena <span class=\"greek\">ἡ</span> <span class=\"greek\">ὁδὸς</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">σάρκα</span> IRo 9:3.—<span class=\"greek\">ἐν</span> <span class=\"greek\">σαρκὶ</span> <span class=\"greek\">πεποιθέναι</span> depositar confiança em coisas terrenas ou vantagens físicas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 3:3</a>f. <span class=\"greek\">εὐπροσωπῆσαι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">σαρκί</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.6.12\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 6:12</a>. Onésimo é um irmão amado de Filemom <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">σαρκὶ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">κυρίῳ</span> tanto como ser humano (=pessoalmente, na relação exterior entre senhor e escravo) quanto como cristão Phlm 16. <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">σαρκὶ</span> <span class=\"greek\">ἐπισκόπῳ</span> IEph 1:3 (cf. IMg 3:2).—HWindisch, Taufe u. Sünde 1908; EBurton, ICC Gal. 1920, 492–95; WSchauf, Sarx 1924; WBieder, Auferstehung des Fleisches od. des Leibes?: TZ 1, ’45, 105–20. Com especial ref. a Paulo: Ltzm., Hdb. exc. sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.7.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 7:14</a> e 8:11; Lohmeyer (<span class=\"greek\">ἁμαρτία</span> 3a); EKäsemann, Leib u. Leib Christi ’33; RGrant, ATR 22, ’40, 199–203; RBultmann, Theologie des NTs ’48, 228–49 (trad. ingl. de KGrobel, ’51 I, 227–59); LMarshall, Challenge of NT Ethics ’47, 267–70; E Schweizer, Die hellenist. Komponente im NT sarx-Begriff: ZNW 48, ’57, 237–53; dois estudos em KStendahl, The Scrolls and the NT, ’57: KKuhn, 94–113 e WDavies, 157–82; JPryke, ‘Spirit’ and ‘Flesh’ in Qumran and NT: RevQ 5, ’65, 346–60; DLys, La chair dans l’AT ’67; ASand, D. Begriff ‘Fleisch’ ’67 (Paulo); RJewett, Paul’s Anthropological Terms ’71, 49–166. Sobre Ign.: CRichardson, The Christianity of Ign. of Ant. ’35, esp. 49 e 61. V. também a lit. s.v. <span class=\"greek\">πνεῦμα</span>, fim.—B. 202. DELG. M-M. EDNT. TW. Spicq. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0320-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σάρος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σάρος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (um masc. raro [Hesych.] em lugar do neut. usual <span class=\"greek\">σάρον</span>. O gênero não pode ser determinado em SIG 1169, 48 <span class=\"greek\">σάρῳ</span> <span class=\"greek\">τινὶ</span> <span class=\"greek\">ἀποκαθαίρειν</span> e Anth. Pal. 11, 207, 4 <span class=\"greek\">σάρον</span> ac.) vassoura Hs 9, 10, 3.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0320-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Σαρούχ</h1><div class=\"entry-meta\"><span>nome próprio; variante</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Σαρούχ</span> v.l. por <span class=\"greek\">Σερούχ</span> (v. esse verbete).</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0320-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σαρόω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σαρόω</span> (forma tardia em lugar de <span class=\"greek\">σαίρω</span> por intermédio de <span class=\"greek\">σάρον</span>; censurada por Phryn., v. Lob.) 1 aor. <span class=\"greek\">ἐσάρωσα</span>. Pass.: 1 aor. <span class=\"greek\">ἐσαρώθην</span>; part. perf. <span class=\"greek\">σεσαρωμένος</span> varrer mediante o uso de uma vassoura, varrer (assim Artem. 2, 33; Apollon. Dysc. p. 253, 7; Geopon. 14, 6, 5; PGiss 11, 19 [II d.C.]) <span class=\"greek\">τὶ</span> algo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.15.8\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 15:8</a>. Pass. (cf. Sb 8000, 17 [III d.C.] <span class=\"greek\">συνσαρωθῆναι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ῥανθῆναι</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">οἶκον</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.44\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:44</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:25</a>: Hs 9, 10, 2. Abs. Hs 9, 10, 3 (Leutzsch, Hermas p. 487 n. 313).—B. 580. DELG s.v. 1 <span class=\"greek\">σαίρω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0320-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Σάρρα, ας, ἡ</h1><div class=\"entry-meta\"><span>nome próprio feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Σάρρα</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (<span class=\"hebrew\">שָׂרָה</span> Gen 17:15; declinado como na LXX, TestAbr; TestLevi 6:8; JosAs 1:8; Joseph., Just.; B-D-F §40; Mlt-H. 144) Sara, esposa de Abraão, mãe de Isaque <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.4.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 4:19</a>; 9:9 (cf. Gen 18:10); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.11\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 3:6</a>; GJs 2:4.—BHHW III 1670. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0320-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Σαρ(ρ)ων, ωνος, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Σαρ</span>(<span class=\"greek\">ρ</span>)<span class=\"greek\">ων</span>, <span class=\"greek\">ωνος</span>, <span class=\"greek\">ὁ</span> (<span class=\"hebrew\">שָׁרוֹן</span> Is 33:9.—O acento não pode ser determinado, embora provavelmente estivesse na segunda sílaba, como em hebr. Além disso, a forma pode ser indecl. B-D-F §56, 2; Mlt-H. 149) Sarom, uma planície ao longo da costa da Palestina, de Jope a Cesareia. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.35\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:35</a> (v.l. <span class=\"greek\">Ἀσσάρων</span>).</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0320-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σατάν, ὁ</h1><div class=\"entry-meta\"><span>nome masculino indeclinável; nome próprio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σατάν</span>, <span class=\"greek\">ὁ</span> indecl. e <span class=\"greek\">σατανᾶς</span>, <span class=\"greek\">ᾶ</span>, <span class=\"greek\">ὁ</span> (o primeiro=hebr. <span class=\"hebrew\">שָׂטָן</span> 3 Km 11:14; Just., D. 103, 5; o segundo Sir 21:27, também TestSol 1:1 D al.; TestJob; Test12Patr; ApcMos 17; Just.=aram. <span class=\"hebrew\">סָטָנָא</span>; por <span class=\"greek\">σατανος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.18\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:18</a> P75 lê <span class=\"greek\">σατανας</span>) literalmente ‘adversário’, em nossa lit. somente como título ou nome: (o) Satanás, em sentido muito especial, o inimigo de Deus e de todos os que pertencem a Deus, simplesmente Satanás, o Inimigo (sobre o conceito de Satanás, v. a lit. s.v. <span class=\"greek\">διάβολος</span> 2), quase sempre com o art. (B-D-F §254, 1), sem ele somente em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.3\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.7\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 12:7</a> e na interpelação pessoal.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:10</a> (aqui, bem como nas duas passagens de Mt e Mk perto do fim deste verbete, sem o art. e no voc.); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:13</a>; 3:26; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.18\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:18</a>; 22:31. Com <span class=\"greek\">διάβολος</span>, do mesmo ser <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.20.2\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 20:2</a>; cf. 2:9f; Pol 7:1 (Just., A I, 28, 1 al.). O Iníquo (Anticristo) aparece <span class=\"greek\">κατ</span>’ <span class=\"greek\">ἐνέργειαν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">σατανᾶ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 2:9</a>. Incita as pessoas ao mal (cf. o uso homérico LfgrE s.v. <span class=\"greek\">δαιμόνι</span>[<span class=\"greek\">ος</span>] col. 198; TestJob 41:5 <span class=\"greek\">Ἐλίους</span> <span class=\"greek\">ἐμπνευσθεὶς</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">Σ</span>. ; 23:11 <span class=\"greek\">ὁ</span> <span class=\"greek\">Σ</span>. … <span class=\"greek\">ἐπλαγίαζεν</span> <span class=\"greek\">αὐτῆς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">καρδίαν</span>; cf. 26:6) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 2:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.12.9\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 12:9</a>. Especialmente culpado de instigar a má ação de Judas ao entrar nesse discípulo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.3\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.27\" target=\"_blank\" rel=\"noopener noreferrer\">J 13:27</a>. Causando enfermidade <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.16\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 13:16</a> (v. <span class=\"greek\">δέω</span> 1b, fim). Daí ser expulso nas curas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:23</a>. Impedindo o apóstolo em seu trabalho <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.18\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 2:18</a> (cf. Julian., Ep. 40 [68] p. 46, 19 Bidez-Cumont <span class=\"greek\">εἰ</span> <span class=\"greek\">μή</span> <span class=\"greek\">τι</span> <span class=\"greek\">δαιμόνιον</span> <span class=\"greek\">γένοιτο</span> <span class=\"greek\">κώλυμα</span>). Fazendo surgir falsas crenças <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 5:15</a>; daí aquele que nega a ressurreição e o juízo ser chamado <span class=\"greek\">πρωτότοκος</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ς</span>. Pol 7:1; Policarpo emprega a mesma expr. ao falar de Marcião, Epil Mosq 3. As perseguições aos cristãos também são inspiradas por Satanás <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:13</a>ab (sobre o <span class=\"greek\">θρόνος</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ς</span>. v. <span class=\"greek\">θρόνος</span> 1b<span class=\"greek\">ε</span>); daí certos judeus hostis aos cristãos serem chamados <span class=\"greek\">συναγωγὴ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ς</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:9</a>; 3:9. Deus o esmagará <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.16.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 16:20</a>. Jesus viu Satanás caindo (ou caído) do céu <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.18\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:18</a> (Burton, Moods and Tenses §146 [deZwaan §148]; FSpitta, ZNW 9, 1908, 160–63; CWebster, ET 57, ’45/46, 52f: <span class=\"greek\">πες</span>. é atemporal e significa ‘eu o observei cair’). Aprisionado, mas novamente libertado após mil anos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.20.7\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 20:7</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">ς</span>. <span class=\"greek\">μετασχηματίζεται</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ἄγγελον</span> <span class=\"greek\">φωτός</span> Satanás se disfarça de anjo de luz <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.14\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 11:14</a> (TestJob 6:4 <span class=\"greek\">μετασχηματισθεὶς</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ἐπαίτην</span> um mendigo; ApcMos 17 <span class=\"greek\">ἐγένετο</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">εἴδει</span> <span class=\"greek\">ἀγγέλου</span>; v. <span class=\"greek\">μετασχηματίζω</span>; sobre o assunto, v. Windisch ad loc.). <span class=\"greek\">ἄγγελος</span> <span class=\"greek\">σατανᾶ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.7\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 12:7</a> (UHeckel, ZNW 84, ’93, 69–75); <span class=\"greek\">ἄγγελοι</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ς</span>. B 18:1 (<span class=\"greek\">ἄγγελος</span> 2c). <span class=\"greek\">αἱ</span> <span class=\"greek\">δυνάμεις</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ς</span>. IEph 13:1 (<span class=\"greek\">δύναμις</span> 5). <span class=\"greek\">τὰ</span> <span class=\"greek\">βαθέα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ς</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.24\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:24</a> (v. <span class=\"greek\">βαθύς</span> 2). <span class=\"greek\">ἡ</span> <span class=\"greek\">ἐξουσία</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ς</span>. o poder de Satanás <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 26:18</a>; final de Mk no ms. Freer, linha 6 (<span class=\"greek\">ἐξουσία</span> 2); ibid. linha 2 <span class=\"greek\">ὁ</span> <span class=\"greek\">αἴων</span> <span class=\"greek\">οὗτος</span> … <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ς</span>. <span class=\"greek\">ἐστιν</span>.—<span class=\"greek\">παραδοῦναί</span> <span class=\"greek\">τινα</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ς</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.5.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 5:5</a> (v. <span class=\"greek\">ὄλεθρος</span>; cf. a inscr. cristã New Docs 3, 83); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 1:20</a> (sobre ambas as passagens, v. <span class=\"greek\">παραδίδωμι</span> 1b).—Em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.16.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 16:23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 8:33</a> Pedro é chamado Satanás por Jesus, porque sua tentativa de desviar Jesus de sua missão divina de aceitar as consequências de seu envolvimento com a humanidade o tornou um tentador de índole diabólica, que poderia frustrar o plano divino de salvação. Esse uso metaf. relaciona-se com o notável veredicto <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:9</a>; 3:9 acima (cf. <span class=\"greek\">διάβολος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.70\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:70</a>; 8:44).—BNoack, Satanás u. Sotería ’48. 1369–80 (lit.). DBS XII 1–47. DNP III 269. DELG. M-M. EDNT. TRE III 608f. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0320-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σάτον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σάτον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (aram. <span class=\"hebrew\">סָאתָא</span>=hebr. <span class=\"hebrew\">סְאָה</span>.—Hg 2:16; Jos., Ant. 9, 85 <span class=\"greek\">ἰσχύει</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">σάτον</span> <span class=\"greek\">μόδιον</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἥμισυ</span> <span class=\"greek\">Ἰταλικόν</span>) uma medida hebraica para produtos secos com capacidade de cerca de treze litros, uma seá, uma medida de treze litros (1/30 de um <span class=\"greek\">κόρος</span>; v. Joseph. acima; v. também <span class=\"greek\">μόδιος</span>). <span class=\"greek\">ἀλεύρου</span> <span class=\"greek\">σάτα</span> <span class=\"greek\">τρία</span> três medidas de farinha = cerca de trinta e cinco litros ou cerca de um bushel de farinha, implicando uma operação de panificação espantosa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:33</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.21\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 13:21</a>. Sobre a estimativa do tamanho da medida, v. Billerb. I 669f; PYadin p. 69 nota.—TRE III 609f M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0320-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Σαῦλος, ου, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Σαῦλος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> Saulo, forma helenizada de <span class=\"hebrew\">שָׁאוּל</span> (Joseph. menciona vários judeus com esse nome; v. índice s.v. <span class=\"greek\">Σαοῦλος</span>), o nome hebraico do apóstolo Paulo (v. <span class=\"greek\">Παῦλος</span> 2 e <span class=\"greek\">Σαούλ</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.58\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:58</a>; 8:1, 3; 9:1, 8, 11, 22, 24; 11:25, 30; 12:25; 13:1f, 7, 9; 22:7 D (<span class=\"greek\">Σαῦλε</span>); 26:14 v.l. (<span class=\"greek\">Σαῦλε</span>).—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0320-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σαφῶς</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σαφῶς</span> (Hom. [<span class=\"greek\">σαφέως</span>]+; inscr., pap., LXX; TestSol 4:2 D; Philo; Jos., Bell. 2, 104 <span class=\"greek\">ς</span>. <span class=\"greek\">ἐπίσταμαι</span>, Ant. 4, 41) adv. de <span class=\"greek\">σαφής</span> (comp. <span class=\"greek\">σαφέστερον</span> Just., A I, 35, 2) relativo a elevado grau de exatidão, claramente, exatamente, muito bem <span class=\"greek\">εἰδέναι</span> (Pla., Ep. 6, 323d, Ep. 7, 324a; Diod S 19, 9, 2; Appian, Bell. Civ. 3, 82 §335; PCairZen 110, 12 [257 a.C.]) 1 Cl 62:3; PtK 3 p. 15, 26. <span class=\"greek\">μανθάνειν</span> (Menand., Epitr. 332 S. [156 Kö.]; Mitt-Wilck. I/2, 6, 4) Dg 11:2. (Com <span class=\"greek\">ἐπιμελῶς</span>) <span class=\"greek\">πυνθάνεσθαι</span> (Menand., Epitr. 877 S. [557 Kö.]) Dg 1.—DELG s.v. <span class=\"greek\">σάφα</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0320-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σβέννυμι</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σβέννυμι</span> fut. <span class=\"greek\">σβέσω</span>; 1 aor. <span class=\"greek\">ἔσβεσα</span>, inf. <span class=\"greek\">σβέσαι</span>. Pass.: 1 fut. <span class=\"greek\">σβεσθήσομαι</span>; 1 aor. <span class=\"greek\">ἐσβέσθην</span> LXX; part. perf. pl. <span class=\"greek\">ἐσβεσμένοι</span> 3 Macc. 6:34 (Hom. et al.; Sb 7033, 46; 67; LXX; TestJob 43:5; TestLevi 4:1; Ar. 5, 3; Just., D. 93, 1; Mel., P. 82, 614; Ath., R. 20 p. 73, 11) fazer com que uma ação, estado ou faculdade cesse de funcionar ou existir, extinguir, apagar</p><p class=\"entry-text\">ⓐ lit. extinguir, apagar <span class=\"greek\">τὶ</span> algo, fogo (Jos., Bell. 7, 405) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.34\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:34</a>. Em linguagem figurada, flechas inflamadas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.16\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 6:16</a>; um pavio fumegante <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:20</a> (Is 42:3). Pass. ser extinto, ser apagado, apagar-se (Artem. 2, 9; Pr 13:9; Philo, Leg. All. 1, 46; TestLevi 4:1) de lâmpadas (v. TestJob 43:5 <span class=\"greek\">λύχνος</span> … <span class=\"greek\">σβεσθείς</span>; PGM 7, 364 <span class=\"greek\">σβέσας</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">λύχνον</span>; Musaeus, Hero and Leander 338) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25:8</a>. Cf. D 16:1. De uma pira <span class=\"greek\">μετ</span>’ <span class=\"greek\">ὀλίγον</span> <span class=\"greek\">σβεννύμενον</span> MPol 11:2. Do fogo do inferno, que <span class=\"greek\">οὐ</span> <span class=\"greek\">σβέννυται</span> (Is 66:24) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.44\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:44</a>, 46, 48; 2 Cl 7:6; 17:5; <span class=\"greek\">μηδέποτε</span> <span class=\"greek\">σβεννύμενον</span> <span class=\"greek\">πῦρ</span> MPol 2:3.</p><p class=\"entry-text\">ⓑ extensão fig. de a, extinguir, sufocar, suprimir (Il. 9, 678 <span class=\"greek\">χόλον</span>; epigrama em louvor de Apolônio de Tiana: New Docs 3, n.º 15, 2 [III/IV d.C.] <span class=\"greek\">ἀμπλακίας</span> ‘faltas’; Pla., Leg. 8, 835d <span class=\"greek\">ὕβριν</span>; 10, 888a <span class=\"greek\">τὸν</span> <span class=\"greek\">θυμόν</span>; Herm. Wr. 12, 6; SSol 8:7 <span class=\"greek\">τὴν</span> <span class=\"greek\">ἀγάπην</span>; 4 Macc 16:4 <span class=\"greek\">τὰ</span> <span class=\"greek\">πάθη</span>; Jos., Bell. 6, 31 <span class=\"greek\">τ</span>. <span class=\"greek\">χαράν</span>, Ant. 11, 40; Just., D. 93, 1 <span class=\"greek\">τὰς</span> <span class=\"greek\">φυσικὰς</span> <span class=\"greek\">ἐννοίας</span>) <span class=\"greek\">τὸ</span> <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">σβέννυτε</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.19\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 5:19</a> (Plut., Mor. 402b <span class=\"greek\">τοῦ</span> <span class=\"greek\">πνεύματος</span> <span class=\"greek\">ἀπεσβεσμένου</span>; Ps.-Plut., Hom. 127 <span class=\"greek\">τὸ</span> <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">κατασβεννύμενον</span>).—DELG. M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0320-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σέ</h1><div class=\"entry-meta\"><span>pronome; remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σέ</span> v. <span class=\"greek\">σύ</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0320-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σεαυτοῦ</h1><div class=\"entry-meta\"><span>pronome reflexivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σεαυτοῦ</span> (não <span class=\"greek\">σαυτοῦ</span> [assim Jos., Ant. 18, 336; Tat. 25, 1], B-D-F §31, 1 e 64, 1; Mlt-H. 180f; Rob. 287), <span class=\"greek\">ῆς</span> (Alcaeus [c. 600 a.C.] et al.; pap., LXX, En, JosAs; ParJer 6:6; EpArist, Just., Tat.) pron. reflexivo da segunda pess. do sing. (Kühner-Bl. I 596ff; B-D-F §283; W-S. §22, 11; Rob. 687–90) empregado somente no gen., dat. e ac. (sobre a substituição de <span class=\"greek\">σεαυτοῦ</span> por <span class=\"greek\">ἑαυτοῦ</span>, v. <span class=\"greek\">ἑαυτοῦ</span> 1b) tu mesmo</p><p class=\"entry-text\">ⓐ gen. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:16</a> v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.22\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:22</a>; 8:13; 9:17 <span class=\"hebrew\">א</span>* P75 (EBammel, NTS 40, ’94, 455f); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.11\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 4:11</a>; Hv 3, 6, 7; m 1:2.</p><p class=\"entry-text\">ⓑ dat. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.17.5\" target=\"_blank\" rel=\"noopener noreferrer\">J 17:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.34\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:34</a>; 16:28; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 2:5</a>; Hm 3:5; 9:1b; 12, 3, 5f. Também <span class=\"greek\">λογίζεσθαι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">σεαυτῷ</span> Hs 9, 2, 6 (um semitismo, cf. TestJob 2:3; Leutzsch, Hermas 486 n. 290).</p><p class=\"entry-text\">ⓒ ac. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:6</a>; 8:4; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.44\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:44</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.14\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 2:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.6.1\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 6:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.4.16\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 4:16</a>b; B 19:3; Dg 2:1; Hm 9:8.—Sobre a cit. de Lev 19:18: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.19.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 19:19</a>; 22:39; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.31\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:31</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.27\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:27</a>; D 1:2, cf. Appian, Bell. Civ. 3, 75 §305: Pansa diz a Otaviano <span class=\"greek\">ἐγὼ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">σῷ</span> <span class=\"greek\">πατρὶ</span> <span class=\"greek\">φίλος</span> <span class=\"greek\">ἦν</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">ἐμαυτῷ</span>; Vi. Aesopi W 31 P.: <span class=\"greek\">θέλω</span> (v. esse verbete 3b=amar) <span class=\"greek\">αὐτὴν</span> (sua esposa) <span class=\"greek\">ὡς</span> <span class=\"greek\">ἐμαυτόν</span>=ed. Eberh. I c. 8 p. 247, 1 <span class=\"greek\">ταύτην</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">ἐμαυτὸν</span> <span class=\"greek\">στέργω</span>.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0320-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σεβάζομαι</h1><div class=\"entry-meta\"><span>verbo depoente</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σεβάζομαι</span> (<span class=\"greek\">σέβας</span> ‘temor reverencial’; v. os quatro verbetes seguintes; dep. (Hom. et al.) 1 aor. <span class=\"greek\">ἐσεβάσθην</span>; =<span class=\"greek\">σέβομαι</span> mostrar reverência a, adorar (Orph., Argon. 550; dito oracular em Eus., PE 9, 10, 4 <span class=\"greek\">σεβαζόμενοι</span> <span class=\"greek\">θεὸν</span> <span class=\"greek\">ἁγνῶς</span>; Ar. 12, 7 [de certos politeístas <span class=\"greek\">ἐσεβάσθησαν</span> <span class=\"greek\">πρόβατον</span>; cf. Hos 10:5 Aq.]) 1 aor. pass. em sentido at. (JosAs 12:6 <span class=\"greek\">σεβασθεῖσα</span> <span class=\"greek\">εἴδωλα</span> <span class=\"greek\">νεκρὰ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">κωφά</span>; Sib-Or 5, 405; 8, 46; v. Aristid. acima) <span class=\"greek\">ἐσεβάσθησαν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐλάτρευσαν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">κτίσει</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">κτίσαντα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:25</a>.—DELG s.v. <span class=\"greek\">σέβομαι</span> II. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0320-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σέβασμα, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σέβασμα</span>, <span class=\"greek\">ατος</span>, <span class=\"greek\">τό</span> (<span class=\"greek\">σεβάζομαι</span>) algo que se relaciona com a atividade devocional, objeto de devoção (assim Dionys. Hal. 1, 30; Wsd 14:20; 15:17; Bel 27 Theod.; Jos., Ant. 18, 344; SibOr 8, 57; Ps.-Clem., Hom. 10, 21 e 22; Ar.) com <span class=\"greek\">θεός</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 2:4</a>. Pl. (ViEzk 2 [p. 74, 8 Sch.=Torrey 23, 1f] <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">εἰδώλων</span> <span class=\"greek\">σεβάσμασι</span>) <span class=\"greek\">τὰ</span> <span class=\"greek\">σεβάσματα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.23\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 17:23</a>. O pl., juntamente com o verbo <span class=\"greek\">ἀναθεωρέω</span>, refere-se ao impacto visual total de uma cidade repleta de monumentos cultuais.—DELG s.v. <span class=\"greek\">σέβομαι</span> II. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0320-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σεβάσμιος, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σεβάσμιος</span>, <span class=\"greek\">ον</span> (<span class=\"greek\">σεβάζομαι</span>; Plut.; Vett. Val. 221, 23; Lucian; Herodian; Jos., Bell. 4, 164, Ant. 18, 349; inscr.; freq. empregado com <span class=\"greek\">ὅρκος</span> nos pap.) digno de veneração, honroso (com <span class=\"greek\">πανάρετος</span>) <span class=\"greek\">πολιτεία</span> 1 Cl 2:8.—DELG s.v. <span class=\"greek\">σέβομαι</span> II.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0320-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σεβαστός, ή, όν</h1><div class=\"entry-meta\"><span>adjetivo; título</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σεβαστός</span>, <span class=\"greek\">ή</span>, <span class=\"greek\">όν</span> (<span class=\"greek\">σεβάζομαι</span>; Dionys. Hal. 2, 75; SIG 820, 6; pap., Philo, Joseph.; empréstimo no rabínico) digno de reverência, reverenciado, augusto, como trad. do lat. Augustus e designação do imperador romano (Paus. 3, 11, 4 <span class=\"greek\">τὸ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">ὄνομα</span> <span class=\"greek\">εἶναι</span> <span class=\"greek\">τούτῳ</span> <span class=\"greek\">Αὔγουστος</span>, <span class=\"greek\">ὅ</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">γλῶσσαν</span> <span class=\"greek\">δύναται</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">Ἑλλήνων</span> <span class=\"greek\">σεβαστός</span>=seu nome é Augusto, que em gr. se traduz por <span class=\"greek\">σεβαστός</span>; Strabo 3, 3, 8; 12, 13, 14; Lucian, Herodian, Philo; Jos., Ant. 16, 173 al.; CIA III 63 [27 a.C.] <span class=\"greek\">ἱερεὺς</span> <span class=\"greek\">θεᾶς</span> <span class=\"greek\">Ῥώμης</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">Σεβαστοῦ</span> <span class=\"greek\">σωτῆρος</span>; IG XII/3, 174 [6 a.C.]; pap. Como epíteto de Antônio Pio, Ar. inscr.; Just., A I, inscr.—EBréhier, ByzZ 15, 1906, 161f; 164f; Hahn 116f; Dssm., LO 306 [LAE 358ff]; HDieckmann, Kaisernamen u. Kaiserbez. bei Lukas: ZKT 43, 1919, 213–34; Goodsp., Probs. 136f) <span class=\"greek\">ὁ</span> <span class=\"greek\">Σεβαστός</span> Sua Majestade o Imperador <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 25:21</a>, 25 (de Nero).—Em <span class=\"greek\">σπεῖρα</span> <span class=\"greek\">Σεβαστή</span> 27:1 (cf. OGI 421), <span class=\"greek\">Σεβαστή</span> é igualmente uma trad. exata do lat. Augusta, um título honorífico freq. dado às tropas auxiliares (Ptolem. traduz esse título por <span class=\"greek\">Σεβαστή</span> em relação a três legiões que o ostentavam: 2, 3, 30; 2, 9, 18; 4, 3, 30) coorte imperial, mas <span class=\"greek\">σπεῖρα</span> <span class=\"greek\">Σεβαστή</span> não pode ser considerada equivalente a <span class=\"greek\">σπεῖρα</span> <span class=\"greek\">Σεβαστηνῶν</span>.—Quanto à lit., v. em <span class=\"greek\">ἑκατοντάρχης</span>.—DELG s.v. <span class=\"greek\">σέβομαι</span>. M-M. TW.</p></section></article>"};
